def parse_expression(s, pos):
    terms = [parse_term(s, pos)]
    while pos[0] < len(s) and s[pos[0]] == '|':
        pos[0] += 1
        terms.append(parse_term(s, pos))
    if len(terms) == 1:
        return terms[0]
    return AlternationNode(terms)

