def parse_atom(s, pos):
    if pos[0] >= len(s):
        return None
    c = s[pos[0]]
    if c == '.':
        pos[0] += 1
        return DotNode()
    elif c == '[':
        return parse_bracket(s, pos)
    elif c == '(':
        return parse_group(s, pos)
    elif c == '\\':
        pos[0] += 1
        if pos[0] < len(s):
            next_c = s[pos[0]]
            pos[0] += 1
            return LiteralNode(next_c)
        else:
            return None
    else:
        pos[0] += 1
        return LiteralNode(c)

def parse_bracket(s, pos):
    pos[0] += 1  # consume '['
    negated = False
    if pos[0] < len(s) and s[pos[0]] == '^':
        negated = True
        pos[0] += 1
    chars = []
    i = pos[0]
    while i < len(s) and s[i] != ']':
        if s[i] == '\\':
            i += 1
            if i < len(s):
                chars.append(s[i])
                i += 1
        else:
            chars.append(s[i])
            i += 1
    pos[0] = i
    pos[0] += 1  # consume ']'
    expanded = []
    j = 0
    while j < len(chars):
        if j + 2 < len(chars) and chars[j+1] == '-':
