        else:
            expanded.append(chars[j])
            j += 1
    return BracketNode(expanded, negated)

def parse_group(s, pos):
    pos[0] += 1  # consume '('
    expr = parse_expression(s, pos)
    if pos[0] < len(s) and s[pos[0]] == ')':
        pos[0] += 1
    return GroupNode(expr)

def matches(node, text, pos, memo):
    if (node, pos) in memo:
        return memo[(node, pos)]
    if node is None:
        return False
    if isinstance(node, LiteralNode):
        if pos < len(text) and text[pos] == node.char:
            result = (True, pos + 1)
        else:
            result = (False, pos)
    elif isinstance(node, DotNode):
        if pos < len(text):
            result = (True, pos + 1)
        else:
            result = (False, pos)
    elif isinstance(node, BracketNode):
        if pos < len(text):
            c = text[pos]
            if (c in node.chars) ^ node.negated:
                result = (True, pos + 1)
            else:
                result = (False, pos)
        else:
            result = (False, pos)
    elif isinstance(node, GroupNode):
        matched, new_pos = matches(node.expr, text, pos, memo)
        result = (matched, new_pos)
    elif isinstance(node, QuantifierNode):
        child = node.child
        q = node.quantifier
        if q == '?':
            # 0 or 1
            zero_matched = (True, pos)
            one_matched, new_pos = matches(child, text, pos, memo)
            if one_matched:
                result = (True, new_pos)
            else:
                result = zero_matched
        elif q == '*':
            # 0 or more
            result = (True, pos)
            current_pos = pos
            while True:
                matched, next_pos = matches(child, text, current_pos, memo)
                if not matched:
                    break
                result = (True, next_pos)
                current_pos = next_pos
        elif q == '+':
            # 1 or more
            matched, new_pos = matches(child, text, pos, memo)
            if not matched:
                result = (False, pos)
            else:
                current_pos = new_pos
                while True:
                    m, next_p = matches(child, text, current_pos, memo)
                    if not m:
                        break
                    current_pos = next_p
                result = (True, current_pos)
        else:
            result = (False, pos)
    elif isinstance(node, ConcatenationNode):
        current_pos = pos
        for factor in node.factors:
            matched, new_pos = matches(factor, text, current_pos, memo)
            if not matched:
                result = (False, pos)
                break
            current_pos = new_pos
        else:
            result = (True, current_pos)
    elif isinstance(node, AlternationNode):
        for term in node.terms:
            matched, new_pos = matches(term, text, pos, memo)
            if matched:
                result = (True, new_pos)
                break
        else:
            result = (False, pos)
    else:
        result = (False, pos)
    memo[(node, pos)] = result
    return result

