def utf8_decode(b):
    output = []
    i = 0
    n = len(b)
    while i < n:
        current = b[i]
        if current <= 0x7F:
            output.append(chr(current))
            i += 1
        elif 0xC2 <= current <= 0xDF:
            if i + 1 >= n:
                output.append('\ufffd')
                i += 1
            else:
                next_byte = b[i + 1]
                if (next_byte & 0xC0) != 0x80:
                    output.append('\ufffd')
                    i += 1
                else:
                    code_point = ((current & 0x1F) << 6) | (next_byte & 0x3F)
                    output.append(chr(code_point))
                    i += 2
        elif current == 0xE0:
            if i + 2 >= n:
                output.append('\ufffd')
