def utf8_decode(b: bytes) -> str:
    result = []
    pos = 0
    while pos < len(b):
        current_byte = b[pos]
        if current_byte < 0x80:
            result.append(chr(current_byte))
            pos += 1
        else:
            n = 0
            if 0xC2 <= current_byte <= 0xDF:
                n = 2
            elif current_byte == 0xE0:
                n = 3
            elif 0xE1 <= current_byte <= 0xEC or 0xEE <= current_byte <= 0xEF:
                n = 3
            elif current_byte == 0xED:
                n = 3
            elif current_byte == 0xF0:
                n = 4
            elif 0xF1 <= current_byte <= 0xF3:
                n = 4
            elif current_byte == 0xF4:
                n = 4
            else:
                result.append('\ufffd')
                pos += 1
                continue

            if pos + n > len(b):
                result.append('\ufffd')
                pos += 1
                continue

            valid = True
            if n == 2:
                next_byte = b[pos + 1]
                if (next_byte & 0xC0) != 0x80:
                    valid = False
            elif n == 3:
                byte2 = b[pos + 1]
                byte3 = b[pos + 2]
                if current_byte == 0xE0:
                    if not (0xA0 <= byte2 <= 0xBF):
                        valid = False
                elif current_byte == 0xED:
                    if not (0x80 <= byte2 <= 0x9F):
                        valid = False
                if (byte2 & 0xC0) != 0x80 or (byte3 & 0xC0) != 0x80:
                    valid = False
            elif n == 4:
                byte2 = b[pos + 1]
                byte3 = b[pos + 2]
                byte4 = b[pos + 3]
                if current_byte == 0xF0:
                    if not (0x90 <= byte2 <= 0xBF):
                        valid = False
                elif current_byte == 0xF4:
                    if not (0x80 <= byte2 <= 0x8F):
                        valid = False
                if (byte2 & 0xC0) != 0x80 or (byte3 & 0xC0) != 0x80 or (byte4 & 0xC0) != 0x80:
                    valid = False

            if not valid:
                result.append('\ufffd')
                pos += 1
            else:
                if n == 2:
                    code = ((current_byte & 0x1F) << 6) | (b[pos + 1] & 0x3F)
                elif n == 3:
                    code = ((current_byte & 0x0F) << 12) | ((b[pos + 1] & 0x3F) << 6) | (b[pos + 2] & 0x3F)
                elif n == 4:
                    code = ((current_byte & 0x07) << 18) | ((b[pos + 1] & 0x3F) << 12) | ((b[pos + 2] & 0x3F) << 6) | (b[pos + 3] & 0x3F)
                result.append(chr(code))
                pos += n
    return ''.join(result)

def utf8_decode(b: bytes) -> str:
    result = []
    i = 0
    n = len(b)

    while i < n:
        current = b[i]
        if current <= 0x7F:
            result.append(chr(current))
            i += 1
            continue

        # Determine sequence length and constraints
        length = None
        constraints = []
        if 0xC2 <= current <= 0xDF:
            length = 2
            constraints = [(0x80, 0xBF)]
        elif current == 0xE0:
            length = 3
            constraints = [(0xA0, 0xBF), (0x80, 0xBF)]
        elif 0xE1 <= current <= 0xEC:
            length = 3
            constraints = [(0x80, 0xBF), (0x80, 0xBF)]
        elif current == 0xED:
            length = 3
            constraints = [(0x80, 0x9F), (0x80, 0xBF)]
        elif 0xEE <= current <= 0xEF:
            length = 3
            constraints = [(0x80, 0xBF), (0x80, 0xBF)]
        elif current == 0xF0:
            length = 4
            constraints = [(0x90, 0xBF), (0x80, 0xBF), (0x80, 0xBF)]
        elif 0xF1 <= current <= 0xF3:
            length = 4
            constraints = [(0x80, 0xBF), (0x80, 0xBF), (0x80, 0xBF)]
        elif current == 0xF4:
            length = 4
            constraints = [(0x80, 0x8F), (0x80, 0xBF), (0x80, 0xBF)]
        else:
            # Invalid starting byte
            result.append('\ufffd')
            i += 1
            continue

        # Check if there are enough bytes remaining
        if i + length > n:
            result.append('\ufffd')
            i += 1
            continue

        # Check continuation bytes
        valid = True
        for j in range(length - 1):
            byte = b[i + 1 + j]
            min_val, max_val = constraints[j]
            if not (min_val <= byte <= max_val):
                valid = False
                break

        if valid:
            # Decode the code point
            seq = b[i:i+length]
            if length == 2:
                code = ((seq[0] & 0x1F) << 6) | (seq[1] & 0x3F)
            elif length == 3:
                code = ((seq[0] & 0x0F) << 12) | ((seq[1] & 0x3F) << 6) | (seq[2] & 0x3F)
            elif length == 4:
                code = ((seq[0] & 0x07) << 18) | ((seq[1] & 0x3F) << 12) | ((seq[2] & 0x3F) << 6) | (seq[3] & 0x3F)
            else:
                code = 0  # Shouldn't happen

            # Check if code is valid Unicode (excluding surrogates and out-of-range)
            if (0 <= code <= 0xD7FF) or (0xE000 <= code <= 0xFFFF) or (0x10000 <= code <= 0x10FFFF):
                result.append(chr(code))
            else:
                result.append('\ufffd')
            i += length
        else:
            result.append('\ufffd')
            i += 1

    return ''.join(result)

import datetime
from typing import Optional

def cron_next(expr: str, after: datetime.datetime) -> Optional[datetime.datetime]:
    def parse_item(item_str: str, min_val: int, max_val: int) -> list:
        if '/' in item_str:
            base_part, step_str = item_str.split('/', 1)
            step = int(step_str)
            if step < 1:
                raise ValueError("Step must be >=1")
        else:
            base_part = item_str
            step = 1

        if base_part == '*':
            start = min_val
            end = max_val
        else:
            if '-' in base_part:
                parts = base_part.split('-')
                if len(parts) != 2:
                    raise ValueError("Invalid range")
                try:
                    a = int(parts[0])
                    b = int(parts[1])
                except ValueError:
                    raise ValueError("Invalid range")
                start = a
                end = b
            else:
                try:
                    start = int(base_part)
                    end = start
                except ValueError:
                    raise ValueError("Invalid number")

        if start < min_val or end > max_val or start > end:
            raise ValueError("Invalid range")

        values = []
        current = start
        while current <= end:
            if current < min_val or current > max_val:
                raise ValueError("Value out of range")
            values.append(current)
            current += step
        return values

    def parse_field(field_str: str, min_val: int, max_val: int) -> tuple:
        is_restricted = not field_str.startswith('*')
        parts = [p.strip() for p in field_str.split(',')]
        all_values = set()
        for part in parts:
            try:
                values = parse_item(part, min_val, max_val)
            except ValueError as e:
                raise ValueError(f"Invalid field {field_str}: {e}")
            all_values.update(values)
        return (sorted(all_values), is_restricted)

    fields_info = [
        (0, 59, "minute"),
        (0, 23, "hour"),
        (1, 31, "day_of_month"),
        (1, 12, "month"),
        (0, 7, "day_of_week")
    ]

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Invalid cron expression")

    parsed_fields = []
    for i in range(5):
        min_val, max_val, name = fields_info[i]
        field_str = fields[i]
        values, is_restricted = parse_field(field_str, min_val, max_val)
        parsed_fields.append((values, is_restricted))

    minute_vals, hour_vals, dom_vals, month_vals, dow_vals = [pf[0] for pf in parsed_fields]
    dom_restricted, dow_restricted = parsed_fields[2][1], parsed_fields[4][1]

    start_time = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    max_time = after + datetime.timedelta(days=3000)

    while start_time <= max_time:
        if start_time >= max_time:
            break

        current_minute = start_time.minute
        current_hour = start_time.hour
        current_dom = start_time.day
        current_month = start_time.month
        current_dow = start_time.weekday() + 1  # Monday is 1, Sunday is 7 (0 is Sunday)
        if current_dow == 0:
            current_dow = 7

        if current_minute not in minute_vals:
            start_time += datetime.timedelta(minutes=1)
            continue

        if current_hour not in hour_vals:
            start_time += datetime.timedelta(minutes=1)
            continue

        if current_month not in month_vals:
            start_time += datetime.timedelta(minutes=1)
            continue

        dom_ok = current_dom in dom_vals if dom_restricted else True
        dow_ok = current_dow in dow_vals if dow_restricted else True

        if dom_restricted and dow_restricted:
            if not (dom_ok or dow_ok):
                start_time += datetime.timedelta(minutes=1)
                continue
        else:
            if not (dom_ok and dow_ok):
                start_time += datetime.timedelta(minutes=1)
                continue

        return start_time

    return None

