        elif field_name == 'hour':
            min_val, max_val = 0, 23
        elif field_name == 'day_of_month':
            min_val, max_val = 1, 31
        elif field_name == 'month':
            min_val, max_val = 1, 12
        elif field_name == 'day_of_week':
            min_val, max_val = 0, 7
        else:
            raise ValueError("Invalid field name")

