        allowed = set()
        items = field_str.split(',')

        for item in items:
            parts = item.split('/')
            step = 1
            if len(parts) == 2:
                step = int(parts[1])
                base_str = parts[0]
            else:
                base_str = parts[0]

            if base_str == '*':
                start, end = min_val, max_val
            elif '-' in base_str:
                a, b = map(int, base_str.split('-'))
                start, end = a, b
            else:
                start = int(base_str)
                end = start

            if step > 1:
                if base_str == '*':
                    end = max_val
                elif '-' not in base_str:
                    end = max_val

            current = start
            while current <= end:
                allowed.add(current)
                current += step

        for num in allowed:
            if not (min_val <= num <= max_val):
                raise ValueError(f"Value {num} out of range for {field_name}")

        return allowed, is_restricted

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Invalid cron expression")

    minute_allowed, minute_restricted = parse_field(fields[0], 'minute')
    hour_allowed, hour_restricted = parse_field(fields[1], 'hour')
