import bisect

class Calendar:

    def __init__(self, k: int):
        self.k = k
        self.events = []

    def book(self, start: int, end: int) -> bool:
        new_events = [(start, 1), (end, -1)]
        temp_events = self.events.copy()
        for event in new_events:
            pos = bisect.bisect_left(temp_events, event)
            temp_events.insert(pos, event)

        current_overlap = 0
        max_overlap = 0
        for time, delta in temp_events:
            current_overlap += delta
            if current_overlap > max_overlap:
                max_overlap = current_overlap

        if max_overlap > self.k:
            return False
        else:
            for event in new_events:
                pos = bisect.bisect_left(self.events, event)
                self.events.insert(pos, event)
            return True

def sudoku_solve(board: list[str]) -> list[str] | None:
    grid = [list(row) for row in board]
    if not is_valid_initial(grid):
        return None
    if solve(grid):
        return [''.join(row) for row in grid]
    else:
        return None

def is_valid_initial(grid):
    # Check rows
    for row in grid:
        nums = [c for c in row if c != '.']
        if len(nums) != len(set(nums)):
            return False
    # Check columns
    for col in range(9):
        nums = []
        for row in range(9):
            c = grid[row][col]
            if c != '.':
                nums.append(c)
        if len(nums) != len(set(nums)):
            return False
    # Check boxes
    for box_row in range(3):
        for box_col in range(3):
            nums = []
            for i in range(3):
                for j in range(3):
                    r = box_row * 3 + i
                    c = box_col * 3 + j
                    val = grid[r][c]
                    if val != '.':
                        nums.append(val)
            if len(nums) != len(set(nums)):
                return False
    return True

def is_valid_placement(grid, row, col, num):
    # Check row
    for j in range(9):
        if grid[row][j] == num:
            return False
    # Check column
    for i in range(9):
        if grid[i][col] == num:
            return False
    # Check box
    box_row = (row // 3) * 3
    box_col = (col // 3) * 3
    for i in range(box_row, box_row + 3):
        for j in range(box_col, box_col + 3):
            if grid[i][j] == num:
                return False
    return True

def solve(grid):
    empty = []
    for i in range(9):
        for j in range(9):
            if grid[i][j] == '.':
                candidates = []
                for num in '123456789':
                    if is_valid_placement(grid, i, j, num):
                        candidates.append(num)
                if not candidates:
                    return False
                empty.append((i, j, candidates))
    if not empty:
        return True
    # Sort by number of candidates (MRV heuristic)
    empty.sort(key=lambda x: len(x[2]))
    i, j, candidates = empty[0]
    for num in candidates:
        grid[i][j] = num
        if solve(grid):
            return True
        grid[i][j] = '.'  # Backtrack
    return False

