                    nums.append(c)
            if len(nums) != len(set(nums)):
                return True
        # Check boxes
        for box_row in range(3):
            for box_col in range(3):
                nums = []
                for i in range(3):
                    for j in range(3):
                        r = box_row * 3 + i
                        c = box_col * 3 + j
                        if board[r][c] != '.':
                            nums.append(board[r][c])
                if len(nums) != len(set(nums)):
                    return True
        return False

    if has_conflict():
        return None

    grid = [list(row) for row in board]

    def is_valid(r, c, num):
        # Check row
        for j in range(9):
            if grid[r][j] == num:
                return False
        # Check column
        for i in range(9):
            if grid[i][c] == num:
                return False
        # Check box
        start_r = (r // 3) * 3
        start_c = (c // 3) * 3
        for i in range(3):
            for j in range(3):
                if grid[start_r + i][start_c + j] == num:
                    return False
        return True

    def backtrack():
        min_options = 10
        best_pos = (-1, -1)
        for i in range(9):
            for j in range(9):
                if grid[i][j] == '.':
                    options = 0
                    for num in '123456789':
                        if is_valid(i, j, num):
                            options += 1
                    if options == 0:
                        return False
                    if options < min_options:
                        min_options = options
                        best_pos = (i, j)
        if best_pos == (-1, -1):
            return True  # Solved
        i, j = best_pos
        for num in '123456789':
            if is_valid(i, j, num):
                grid[i][j] = num
                if backtrack():
                    return True
                grid[i][j] = '.'
        return False

    if backtrack():
        return [''.join(row) for row in grid]
    else:
        return None

import sys
from collections import deque

def min_semesters(n: int, relations: list[list[int]], k: int) -> int:
    prerequisites = [[] for _ in range(n + 1)]
    for a, b in relations:
        prerequisites[b].append(a)

    max_mask = 1 << n
    bits_count = [0] * max_mask
    for mask in range(max_mask):
        bits_count[mask] = bin(mask).count('1')

    INF = float('inf')
    distance = [INF] * max_mask
    distance[0] = 0
    queue = deque([0])

    while queue:
        current = queue.popleft()
        if current == (1 << n) - 1:
            return distance[current]

        available_mask = 0
        for c in range(1, n + 1):
            available = True
            for p in prerequisites[c]:
                if not (current & (1 << (p - 1))):
                    available = False
                    break
            if available:
                available_mask |= 1 << (c - 1)

        subset = available_mask
        while True:
            if bits_count[subset] <= k:
                next_mask = current | subset
                if distance[next_mask] > distance[current] + 1:
                    distance[next_mask] = distance[current] + 1
                    queue.append(next_mask)
            if subset == 0:
                break
            subset = (subset - 1) & available_mask

    return -1

