from itertools import combinations

def min_semesters(n: int, relations: list[list[int]], k: int) -> int:
    prereq_masks = [0] * (n + 1)
    for a, b in relations:
        prereq_masks[b] |= 1 << (a - 1)

    target = (1 << n) - 1
    distance = [float('inf')] * (1 << n)
    distance[0] = 0
    q = deque([0])

    while q:
        current = q.popleft()
        if current == target:
            return distance[current]
        available = []
        for course in range(n):
            if (current & (1 << course)) == 0:
                course_number = course + 1
                if (current & prereq_masks[course_number]) == prereq_masks[course_number]:
                    available.append(course)
        m = len(available)
        max_take = min(k, m)
        for s in range(1, max_take + 1):
            for subset in combinations(available, s):
                mask = 0
                for c in subset:
                    mask |= 1 << c
                new_state = current | mask
                if distance[new_state] > distance[current] + 1:
                    if distance[new_state] == float('inf'):
                        q.append(new_state)
                    distance[new_state] = distance[current] + 1
    return distance[target]

