        result = defaultdict(int)
        for exp, coeff in p1.items():
            result[exp] += coeff
        for exp, coeff in p2.items():
            result[exp] += coeff
        return {exp: coeff for exp, coeff in result.items() if coeff != 0}

    def multiply_polys(p1, p2):
        result = defaultdict(int)
        for exp1, coeff1 in p1.items():
            for exp2, coeff2 in p2.items():
                new_exp = exp1 + exp2
                new_coeff = coeff1 * coeff2
                result[new_exp] += new_coeff
        return {exp: coeff for exp, coeff in result.items() if coeff != 0}

    def negate_poly(p):
        return {exp: -coeff for exp, coeff in p.items()}

    def poly_power(p, exponent):
