        return []

    # Coordinate compression
    sorted_unique = sorted(set(nums))
    max_rank = len(sorted_unique)
    ft = FenwickTree(max_rank)

    res = []
    for x in reversed(nums):
        r = bisect.bisect_left(sorted_unique, x) + 1  # 1-based rank
        count = ft.query(r - 1)
        res.append(count)
        ft.update(r)

    return res[::-1]

