def skyline(buildings: list[list[int]]) -> list[list[int]]:
    events = []
    for L, R, H in buildings:
        events.append((L, 1, H))
        events.append((R, 0, H))

    events.sort(key=lambda x: (x[0], x[1]))

    heap = []
    counter = defaultdict(int)
    result = []
    prev_height = 0

    for event in events:
        x, typ, h = event
        if typ == 1:
            heapq.heappush(heap, -h)
            counter[h] += 1
        else:
            counter[h] -= 1

        while heap:
            current_top = -heap[0]
            if counter[current_top] > 0:
                break
            else:
                heapq.heappop(heap)

        current_max = 0
        if heap:
            current_max = -heap[0]

        if current_max != prev_height:
            result.append([x, current_max])
            prev_height = current_max

    if not result:
        result.append([0, 0])

    return result

