def trap_rain_2d(height: list[list[int]]) -> int:
    if not height or not height[0]:
        return 0
    m = len(height)
    n = len(height[0])
    if m < 3 or n < 3:
        return 0

    visited = [[False for _ in range(n)] for _ in range(m)]
    heap = []

    for r in range(m):
        for c in range(n):
            if r == 0 or r == m - 1 or c == 0 or c == n - 1:
                heapq.heappush(heap, (height[r][c], r, c))
                visited[r][c] = True

    total = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        h, r, c = heapq.heappop(heap)
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc]:
                visited[nr][nc] = True
                neighbor_h = height[nr][nc]
                added = max(0, h - neighbor_h)
                total += added
                new_h = max(h, neighbor_h)
                heapq.heappush(heap, (new_h, nr, nc))

    return total

