def min_window_subseq(s: str, t: str) -> str:
    if not t or not s:
        return ""

    # Step 1: Find the end of the first occurrence of t in s
    t_len = len(t)
    s_len = len(s)
    end = -1
    t_ptr = 0

    for i in range(s_len):
        if s[i] == t[t_ptr]:
            t_ptr += 1
            if t_ptr == t_len:
                end = i
                break

    if end == -1:
        return ""

    # Step 2: Backtrack from end to find the earliest start
    start = end
    t_ptr = t_len - 1  # start from the end of t

    for i in range(end, -1, -1):
        if s[i] == t[t_ptr]:
            t_ptr -= 1
            if t_ptr < 0:
                start = i
                break

    return s[start:end+1]

