class Node:
    def __init__(self, type_, *children):
        self.type = type_
        self.children = children

    def __repr__(self):
        return f"Node({self.type}, {self.children})"

def tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break
        c = s[i]
        if c.isalpha():
            start = i
            while i < n and s[i].isalpha():
                i += 1
            tokens.append(s[start:i])
        elif c in '!&|()':
            tokens.append(c)
            i += 1
        elif c == '-':
            if i + 1 < n and s[i+1] == '>':
                tokens.append('->')
                i += 2
            else:
                raise ValueError("malformed formula")
        elif c == '<':
            if i + 2 < n and s[i+1] == '-' and s[i+2] == '>':
                tokens.append('<->')
                i += 3
            else:
                raise ValueError("malformed formula")
        else:
            raise ValueError("malformed formula")
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def parse(self):
        return self.parse_equivalence()

    def current(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        tok = self.current()
        self.pos += 1
        return tok

    def parse_equivalence(self):
        expr = self.parse_implication()
        while self.current() == '<->':
            self.consume()
            right = self.parse_implication()
            expr = Node('EQUIVALENCE', expr, right)
        return expr

    def parse_implication(self):
        expr = self.parse_or()
        while self.current() == '->':
            self.consume()
            right = self.parse_implication()
            expr = Node('IMPLICATION', expr, right)
        return expr

    def parse_or(self):
        expr = self.parse_and()
        while self.current() == '|':
            self.consume()
            right = self.parse_or()
            expr = Node('OR', expr, right)
        return expr

    def parse_and(self):
        expr = self.parse_not()
        while self.current() == '&':
            self.consume()
            right = self.parse_and()
            expr = Node('AND', expr, right)
        return expr

    def parse_not(self):
        if self.current() == '!':
            self.consume()
            expr = self.parse_not()
            return Node('NOT', expr)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.current()
        if tok == '(':
            self.consume()
            expr = self.parse_equivalence()
            if self.current() != ')':
                raise ValueError("malformed formula")
            self.consume()
            return expr
        elif tok and tok.isalpha():
            self.consume()
            return Node('VAR', tok)
        else:
            raise ValueError("malformed formula")

def evaluate(node, var_values):
    if node.type == 'VAR':
        return var_values[node.children[0]]
    elif node.type == 'NOT':
        return not evaluate(node.children[0], var_values)
    elif node.type == 'AND':
        return evaluate(node.children[0], var_values) and evaluate(node.children[1], var_values)
    elif node.type == 'OR':
        return evaluate(node.children[0], var_values) or evaluate(node.children[1], var_values)
    elif node.type == 'IMPLICATION':
        return not evaluate(node.children[0], var_values) or evaluate(node.children[1], var_values)
    elif node.type == 'EQUIVALENCE':
        return evaluate(node.children[0], var_values) == evaluate(node.children[1], var_values)
    else:
        raise ValueError("Unknown node type")

def get_vars(node, vars_set):
    if node.type == 'VAR':
        vars_set.add(node.children[0])
    else:
        for child in node.children:
            get_vars(child, vars_set)

