    vars_a = set()
    get_vars(ast_a, vars_a)
    vars_b = set()
    get_vars(ast_b, vars_b)
    all_vars = vars_a.union(vars_b)

    if len(all_vars) > 12:
        raise ValueError("too many variables")

    var_list = list(all_vars)
    n = len(var_list)

    for mask in range(0, 1 << n):
        var_values = {}
        for i in range(n):
            var = var_list[i]
            var_values[var] = (mask >> i) & 1

        val_a = evaluate(ast_a, var_values)
        val_b = evaluate(ast_b, var_values)
        if val_a != val_b:
            return False

    return True

