        elif c == '<':
            if i + 2 < n and s[i+1] == '-' and s[i+2] == '>':
                tokens.append('<- ->')
                tokens[-1] = '<->'
                i += 3
            else:
                raise ValueError("Invalid token '<'")
        elif c.islower():
            j = i
            while j < n and s[j].islower():
