class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def parse(self):
        expr = self.parse_equiv()
        if self.pos != len(self.tokens):
            raise ValueError("Unexpected tokens remaining")
        return expr

    def parse_equiv(self):
        left = self.parse_implies()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '<->':
            self.pos += 1
            right = self.parse_implies()
            left = Equiv(left, right)
        return left

    def parse_implies(self):
        left = self.parse_or()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '->':
            self.pos += 1
            right = self.parse_implies()
            left = Implies(left, right)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '|':
            self.pos += 1
            right = self.parse_and()
            left = Or(left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.pos < len(self.tokens) and self.tokens[self.pos] == '&':
            self.pos += 1
            right = self.parse_not()
            left = And(left, right)
        return left

    def parse_not(self):
        if self.pos < len(self.tokens) and self.tokens[self.pos] == '!':
            self.pos += 1
            expr = self.parse_not()
            return Not(expr)
        else:
            return self.parse_primary()

    def parse_primary(self):
        if self.pos < len(self.tokens) and self.tokens[self.pos] == '(':
            self.pos += 1
            expr = self.parse_equiv()
            if self.pos >= len(self.tokens) or self.tokens[self.pos] != ')':
                raise ValueError("Missing closing parenthesis")
            self.pos += 1
            return expr
        else:
            if self.pos >= len(self.tokens):
                raise ValueError("Unexpected end of input")
            token = self.tokens[self.pos]
            if token in ['!', '&', '|', '->', '<->']:
                raise ValueError(f"Unexpected operator {token} in primary")
            self.pos += 1
            return Var(token)

def get_vars(node):
    vars = set()
    stack = [node]
    while stack:
        current = stack.pop()
        if isinstance(current, Var):
            vars.add(current.name)
        elif isinstance(current, Not):
            stack.append(current.expr)
        elif isinstance(current, (And, Or, Implies, Equiv)):
            stack.append(current.left)
            stack.append(current.right)
    return vars

def evaluate(node, variables):
    if isinstance(node, Var):
        return variables[node.name]
    elif isinstance(node, Not):
        return not evaluate(node.expr, variables)
    elif isinstance(node, And):
        return evaluate(node.left, variables) and evaluate(node.right, variables)
    elif isinstance(node, Or):
        return evaluate(node.left, variables) or evaluate(node.right, variables)
    elif isinstance(node, Implies):
        a = evaluate(node.left, variables)
        b = evaluate(node.right, variables)
        return not a or b
    elif isinstance(node, Equiv):
        a = evaluate(node.left, variables)
        b = evaluate(node.right, variables)
        return a == b

