            elif s[i] in '!&|':
                tokens.append(s[i])
                i += 1
            elif s[i] == '-':
                if i + 1 < len(s) and s[i+1] == '>':
                    tokens.append('->')
                    i += 2
                else:
                    raise ValueError("Invalid token '-' not followed by '>'")
            elif s[i] == '<':
                if i + 2 < len(s) and s[i+1] == '-' and s[i+2] == '>':
                    tokens.append('<->')
                    i += 3
                else:
                    raise ValueError("Invalid token '<' not followed by '-' and '>'")
            else:
                raise ValueError(f"Invalid character '{s[i]}'")
        return tokens

    op_info = {
        '!': {'prec': 5, 'assoc': 'right'},
        '&': {'prec': 4, 'assoc': 'left'},
        '|': {'prec': 3, 'assoc': 'left'},
        '->': {'prec': 2, 'assoc': 'right'},
        '<->': {'prec': 1, 'assoc': 'left'},
    }

    def parse_to_rpn(tokens):
        output = []
        stack = []
        for token in tokens:
            if token in op_info:
                while stack:
                    top = stack[-1]
                    if top == '(':
                        break
                    top_info = op_info[top]
                    current_info = op_info[token]
                    if (current_info['assoc'] == 'left' and top_info['prec'] >= current_info['prec']) or \
                       (current_info['assoc'] == 'right' and top_info['prec'] > current_info['prec']):
                        output.append(stack.pop())
                    else:
                        break
                stack.append(token)
            elif token == '(':
                stack.append('(')
            elif token == ')':
                while stack and stack[-1] != '(':
                    output.append(stack.pop())
                if not stack or stack[-1] != '(':
                    raise ValueError("Mismatched parentheses")
                stack.pop()
            else:
                output.append(token)
        while stack:
            if stack[-1] == '(':
                raise ValueError("Mismatched parentheses")
            output.append(stack.pop())
        return output

    def evaluate_rpn(rpn, variables):
        stack = []
        for token in rpn:
            if token in op_info:
                if token == '!':
                    a = stack.pop()
                    stack.append(not a)
                else:
                    b = stack.pop()
                    a = stack.pop()
                    if token == '&':
                        stack.append(a and b)
                    elif token == '|':
                        stack.append(a or b)
                    elif token == '->':
                        stack.append(not a or b)
                    elif token == '<->':
                        stack.append(a == b)
                    else:
                        raise ValueError(f"Unknown operator {token}")
            else:
                stack.append(variables[token])
        if len(stack) != 1:
            raise ValueError("Invalid RPN expression")
        return stack[0]

    # Parse both formulas
    tokens_a = tokenize(a)
    tokens_b = tokenize(b)

    try:
        rpn_a = parse_to_rpn(tokens_a)
        rpn_b = parse_to_rpn(tokens_b)
    except ValueError as e:
        raise ValueError(f"Malformed formula: {e}")

    # Collect variables from both formulas
    variables = set()
    for token in tokens_a + tokens_b:
        if token not in op_info and token not in '()':
            variables.add(token)

    variables = list(variables)
    num_vars = len(variables)
    if num_vars > 12:
        raise ValueError("Too many variables")

    # Check all possible assignments
