            assignment[var] = bool(val & 1)
            val >>= 1
        try:
            result_a = evaluate_rpn(rpn_a, assignment)
            result_b = evaluate_rpn(rpn_b, assignment)
        except KeyError as e:
            raise ValueError(f"Variable {e} not found in assignment")
        if result_a != result_b:
            return False
    return True

def determinant(m: list[list[int]]) -> int:
    n = len(m)
    if n == 0:
        return 1
    mat = [row[:] for row in m]
    swaps = 0
    d_prev = 1

    for k in range(n):
        # Find pivot row
        if mat[k][k] == 0:
            pivot_row = -1
            for i in range(k + 1, n):
                if mat[i][k] != 0:
                    pivot_row = i
                    break
            if pivot_row == -1:
                return 0
            mat[k], mat[pivot_row] = mat[pivot_row], mat[k]
            swaps += 1

        # Eliminate rows below pivot
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                mat[i][j] = (mat[i][j] * mat[k][k] - mat[i][k] * mat[k][j]) // d_prev

        d_prev = mat[k][k]

    det = mat[-1][-1]
    if swaps % 2 == 1:
        det = -det
    return det

def determinant(m: list[list[int]]) -> int:
