def next_palindrome(s: str) -> str:
    n = len(s)
    mid = (n + 1) // 2
    left_part = s[:mid]

    def increment(s_num):
        s_list = list(s_num)
        i = len(s_list) - 1
        while i >= 0 and s_list[i] == '9':
            s_list[i] = '0'
            i -= 1
        if i == -1:
            return '1' + '0' * len(s_num)
        else:
            s_list[i] = str(int(s_list[i]) + 1)
            return ''.join(s_list)

    candidate = left_part + left_part[:-1][::-1]
    if candidate > s:
        return candidate

    new_left = increment(left_part)
    new_candidate = new_left + new_left[:-1][::-1]
    if len(new_candidate) == n:
        return new_candidate
    else:
        return '1' + '0' * (n - 1) + '1'

