    def count_prefix(x: int, limit: int) -> int:
        if x == 0:
            return 0
        m = len(str(x))
        total = 0
        l = m
        while True:
            lower = x * (10 ** (l - m))
            if lower > limit:
                break
            upper = (x + 1) * (10 ** (l - m)) - 1
            if upper > limit:
                upper = limit
            total += upper - lower + 1
            l += 1
        return total

    current_prefix = 0
    remaining_k = k

    while True:
        if current_prefix == 0:
            digits = range(1, 10)
        else:
            digits = range(0, 10)
        found = False
        for d in digits:
            candidate = current_prefix * 10 + d
            if candidate > n:
                continue
            cnt = count_prefix(candidate, n)
            if cnt >= remaining_k:
                current_prefix = candidate
                found = True
                break
            else:
                remaining_k -= cnt
        if not found:
            raise ValueError("No valid digit found")
        if 1 <= current_prefix <= n and remaining_k == 1:
            return current_prefix

