def fraction_to_base(p: int, q: int, b: int) -> str:
    if q == 0:
        raise ValueError("Denominator cannot be zero.")
    if b < 2 or b > 36:
        raise ValueError("Base must be between 2 and 36.")

    sign = '-' if (p < 0) ^ (q < 0) else ''
    p_abs = abs(p)
    q_abs = abs(q)

    integer_part = p_abs // q_abs
    remainder = p_abs % q_abs

    if remainder == 0:
        return sign + digits_to_str(integer_part, b)

    digits = []
    remainders = {}
    index = 0
    current_remainder = remainder

    while current_remainder != 0 and current_remainder not in remainders:
        remainders[current_remainder] = index
        current_remainder *= b
        digit = current_remainder // q_abs
        digits.append(digit)
        current_remainder %= q_abs
        index += 1

    if current_remainder == 0:
        fractional_part = ''.join(digits_to_str(d, b) for d in digits)
    else:
        repeat_start = remainders[current_remainder]
        non_repeating = digits[:repeat_start]
        repeating = digits[repeat_start:]
        fractional_part = ''.join(digits_to_str(d, b) for d in non_repeating) + '(' + ''.join(digits_to_str(d, b) for d in repeating) + ')'

    integer_str = digits_to_str(integer_part, b) if integer_part != 0 else '0'
    return sign + integer_str + '.' + fractional_part if fractional_part else sign + integer_str

