                char = s[i]
                new_res = [a + char for a in res]
                res = new_res
                i += 1
        return res, i

    expanded, _ = parse(expr, 0)
    return sorted(list(set(expanded)))

def brace_expansion(expr: str) -> list[str]:
    def find_closing_brace(s, start):
        depth = 1
        i = start + 1
        while i < len(s):
            if s[i] == '{':
                depth += 1
            elif s[i] == '}':
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return i

    def split_comma(s):
        parts = []
        current = []
        depth = 0
        for c in s:
            if c == ',' and depth == 0:
                parts.append(''.join(current))
                current = []
            else:
                current.append(c)
                if c == '{':
                    depth += 1
                elif c == '}':
                    depth -= 1
        parts.append(''.join(current))
        return parts

    def parse(s, i):
        if i >= len(s):
            return ([""], i)
        if s[i] == '{':
            end = find_closing_brace(s, i)
            content = s[i+1:end]
            parts = split_comma(content)
            expansions = []
            for part in parts:
                part_exp, _ = parse(part, 0)
                expansions.extend(part_exp)
            next_i = end + 1
            rest_exp, rest_i = parse(s, next_i)
            combined = [a + b for a in expansions for b in rest_exp]
            return (combined, rest_i)
        else:
            current_char = s[i]
            next_i = i + 1
            rest_exp, rest_i = parse(s, next_i)
            combined = [current_char + s_rest for s_rest in rest_exp]
            return (combined, rest_i)

    result, _ = parse(expr, 0)
    return sorted(list(set(result)))
